import {topics} from './explore-data.js';
import {createExplorationField} from './explore-field.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
const content=$('#content'),field=createExplorationField($('#field'));let current='me';
const topic=id=>topics.find(t=>t.id===id)||topics[0];
const links=items=>items.map(x=>`<a href="${esc(x.url)}" ${/^https:/.test(x.url)?'target="_blank" rel="noopener noreferrer"':''}>${esc(x.label)} ↗</a>`).join('');
function work(t){return `<div class="section-head"><h2>作品</h2><span>${t.items.length} 个项目</span></div><div class="work-grid">${t.items.map((i,n)=>`<details class="project" id="item-${esc(i.id)}"><summary><div class="project-art"><img src="./assets/motif-${esc(i.motif)}.webp" alt="" loading="lazy"></div><div class="project-label"><div><h3>${esc(i.name)}</h3><p>${esc(i.short)}</p></div><span class="project-arrow" aria-hidden="true">${arrow}</span></div></summary><div class="project-details"><p>${i.facts.map(esc).join(' / ')}</p><div class="project-links">${links(i.links)}</div></div></details>`).join('')}</div>`;}
function likes(t){let music=t.items.slice(0,3),novels=t.items.slice(3);const rows=list=>list.map(i=>`<a class="like-row" id="item-${esc(i.id)}" href="${esc(i.links[0].url)}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(i.name)}</strong><small>${esc(i.short)}</small></span>${arrow}</a>`).join('');return `<div class="section-head"><h2>喜欢</h2><span>声音与故事</span></div><div class="likes-layout"><div class="likes-intro"><p>有些喜欢，<br>不用解释。</p><img src="./assets/motif-voice.webp" alt="" loading="lazy"></div><div class="likes-collections"><section><h3>音乐 <span>JPOP</span></h3>${rows(music)}</section><section><h3>视觉小说 <span>VISUAL NOVEL</span></h3>${rows(novels)}</section></div></div>`;}
function me(){return `<div class="section-head"><h2>正在探索</h2><span>07 · INFP</span></div><div class="explore-topics"><span>AI 与应用</span><span>机器人</span><span>无人机</span><span>交互与创作</span></div><div class="home-sections"><section class="home-section"><h2>灵感收藏</h2><p>音乐、视觉小说，以及更多喜欢的东西。</p><button data-go="likes">看看收藏 ${arrow}</button></section><section class="home-section"><h2>碎片</h2><p>还没有记录，之后慢慢写。</p></section><section class="home-section"><h2>联系与合作</h2><p>期待有趣的想法和合作。</p><a href="https://github.com/voicepeak" target="_blank" rel="noopener noreferrer">GitHub ↗</a></section></div>`;}

function parse(){let h=decodeURIComponent(location.hash);if(h==='#projects'||h==='#work')return {id:'work'};if(h==='#likes'||h==='#picks')return {id:'likes'};let old=h.match(/^#(project|favorite)\/([^/]+)$/);if(old)return{id:old[1]==='project'?'work':'likes',item:old[2]};let m=h.match(/^#\/(me|work|likes)(?:\/([^/]+))?/);return m?{id:m[1],item:m[2]==='list'?null:m[2]}:{id:'me'};}
function render(id,{item,scroll=false}={}){const t=topic(id);current=t.id;document.body.dataset.topic=t.id;document.title=t.nav+' · 纪';$('#stage-title').textContent=t.title;$('#stage-subtitle').textContent=t.subtitle;$('#stage-meta').textContent=t.id==='me'?'JI / 个人站点':t.id==='work'?'PROJECTS / 作品':'COLLECTION / 收藏';document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.topic===t.id)));content.innerHTML=t.id==='work'?work(t):t.id==='likes'?likes(t):me();field?.setSequence([t.motif],0);if(item){const el=document.getElementById('item-'+item);if(el){if(el.tagName==='DETAILS')el.open=true;requestAnimationFrame(()=>el.scrollIntoView({block:'center'}));}}else if(scroll)window.scrollTo({top:0,behavior:'smooth'});}
content.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(b.dataset.go);});
$('.stage-action').addEventListener('click',e=>{e.preventDefault();content.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
function go(id){if(id===current){window.scrollTo({top:0,behavior:'smooth'});return;}location.hash='#/'+id;}
document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.topic)));$('#next-topic').addEventListener('click',()=>go(topics[(topics.findIndex(t=>t.id===current)+1)%topics.length].id));window.addEventListener('hashchange',()=>{const r=parse();render(r.id,{item:r.item,scroll:!r.item});});
$('#motion-toggle').addEventListener('click',()=>{const b=$('#motion-toggle'),paused=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(paused));b.setAttribute('aria-label',paused?'播放字符动画':'暂停字符动画');b.querySelector('svg').innerHTML=paused?'<path d="m7 5 7 5-7 5z"/>':'<path d="M7 5v10m6-10v10"/>';field?.setPaused(paused);});
$('#field').addEventListener('pointermove',e=>field?.move(e));$('#field').addEventListener('pointerleave',()=>field?.leave());$('#field').addEventListener('click',e=>field?.pulse(e));
const initial=parse();render(initial.id,{item:initial.item});window.__JI_SHALLOW__={render,field,get topic(){return current;}};
